33	     * Make this animal act - that is: make it do
34	     * whatever it wants/needs to do.
35	     * Checks if the time of day matches if the animal is nocturnal or not,
36	     * then attempts to find food and move.
37	     * @param newAnimals A list to receive newly born animals.
38	     * @param weather The weather condition of the simulation.
39	     */
40	    public void act(List<Actor> newAnimals, WeatherCond weather)
41	    {
42	        super.act(newAnimals,weather);
43	        incrementHunger();
44	        if(isAlive()&&(getTime().isDay() != nocturnal)) {
45	            giveBirth(newAnimals);            
46	            // Move towards a source of food if found.
47	            Location newLocation = null;
48	            if (getField().getWeatherAttributeValueAt("visibility", getLocation()) > 0.4){
49	                newLocation = findFood();
50	            }
51	            if(newLocation == null) { 
52	                // No food found - try to move to a free location.
53	                newLocation = getField().freeAdjacentLocation(this, getLocation());
54	            }
55	            // See if it was possible to move.
56	            if(newLocation != null) {
57	                setLocation(newLocation);
58	            }
59	            else {
60	                // Overcrowding.
61	                setDead();
62	            }
63	        }
64	    }
65	
66	    /**
67	     * Make this animal more hungry. This could result in the animal's death.
68	     */
69	    private void incrementHunger()
70	    {
71	        foodLevel--;
72	        if(foodLevel <= 0) {
73	            setDead();
74	        }
75	    }
76	
77	    /**
78	     * Checks if the animal is female and looks for a mate
79	     * @param newAnimals The List of new animals that have been born to add to the simulator List of actors
80	     */
81	    protected void giveBirth(List<Actor> newAnimals)
82	    {
83	        // New animals are born into adjacent locations.
84	        // Get a list of adjacent free locations.
85	        if (female&&findMate()) {
86	            super.giveBirth(newAnimals);
87	        }
88	    }
89	
90	    /**
91	     * Searches for a mate to breed with.
92	     * Searches first for an adjacent animal of the same dynamic type,
93	     * then if that animal is male.
94	     * @return true if a mate is found.
95	     */
96	    protected boolean findMate()
97	    {
98	        Field field = getField();
99	        for(Location where : field.adjacentLocations(getLocation())) {
100	            Object actor = field.getObjectAt(where);
101	            if (actor instanceof Animal) {
102	                Animal animal = (Animal) actor;
103	                if (animal.getClass() == getClass() && !animal.female){
104	                    giveDiseases(animal);
105	                    return true;
106	                }
107	            }
108	        }
109	        return false;
110	    }
111	
112	    /**
113	     * Transfer diseases between mates. Snapshot own diseases first to avoid
114	     * re-sending diseases that were just received from the mate.
115	     * @param mate The male mate that the female breeds with.
116	     */
117	    protected void giveDiseases(Animal mate)
118	    {
119	        Set<Disease> ownDiseasesSnapshot = new HashSet<>(setDiseases);
120	        for (Disease disease: mate.setDiseases){
121	            if (disease.isSpreadByBirth()){
122	                setDiseases.add(disease);
123	            }
124	        }
125	        for (Disease disease: ownDiseasesSnapshot){
126	            if (disease.isSpreadByBirth()){
127	                mate.getActorDiseaseSet().add(disease);
128	            }
129	        }
130	    }
131	
132	    /**
133	     * Look for prey adjacent to the current location.
134	     * Only the first live prey is eaten.
135	     * @return Where food was found, or null if it wasn't.
136	     */
137	    protected Location findFood()
138	    {
139	        Field field = getField();
140	        for(Location where : field.adjacentLocations(getLocation())) {
141	            if ((canMoveOnLand() && canMoveOnWater()) || (field.isUnderWater(where.getRow(), where.getCol()) && canMoveOnWater()) || (!field.isUnderWater(where.getRow(), where.getCol()) && canMoveOnLand())) {
142	                Object actor = field.getObjectAt(where);
143	                if (actor instanceof Actor) {
144	                    Actor prey = (Actor) actor;
145	                    Integer foodValue = getPreyFoodValuesMap().get(prey.getClass());
146	                    if(foodValue != null && prey.isAlive()) {
147	                        for (Disease disease: prey.setDiseases){
148	                            if (disease.isSpreadByEating() && disease.getActorsAffectedMap().containsKey(getClass())){
149	                                setDiseases.add(disease);
150	                            }
151	                        }
152	                        prey.setDead();
153	                        foodLevel = Math.min(foodLevel + foodValue, getMaxFood());
154	                        return where;
155	                    }
156	                }
157	            }
158	        }
159	        return null;
160	    }
