163	     * Returns how many animals are produced during birth.
164	     * Uses the abstract breeding parameters defined by each subclass.
165	     * @return The number of births (may be zero).
166	     */
167	    public int breed()
168	    {
169	        Random rand = Randomizer.getRandom();
170	        if(canBreed() && rand.nextDouble() <= getBreedingProbability()) {
171	            return rand.nextInt(getMaxLitterSize()) + 1;
172	        }
173	        return 0;
174	    }
