182	    abstract protected double getBreedingProbability();
183	    abstract protected int getMaxLitterSize();
184	
185	    abstract protected Animal spawnOffspring(Location loc, Set<Disease> parentDiseases);
186	    abstract protected Animal spawnRandom(Location loc);
